async function handleMessage(msg: Message) {
  const seen = await db.processedMessages.has(msg.id); // dedup store
  if (seen) return; // duplicate delivery, already applied
  await db.transaction(async (tx) => {
    await applyEffect(tx, msg);       // business change
    await tx.processedMessages.add(msg.id); // same tx = atomic with effect
  });
}

